40	static void handle_rx_message(twai_message_t message) {
41	    // log received message for debugging
42	    // ESP_LOGI(TAG, "Received CAN message: ID=0x%03" PRIX32 ", DLC=%d", message.identifier, message.data_length_code);    
43	    
44	    // Switch-case based parsing logic based on CAN Message Identifier
45	    switch (message.identifier) {
46	        
47	        case 0x06214000: { // Ignition Status & Fuel Level
48	            uint8_t new_ignition = ((uint8_t)message.data[2] & 0x40) ? 1 : 0;
49	            
50	            if (current_can_data.ignition == 0 && new_ignition == 1) {
51	                can_app_load_fuel_consumption();
52	                ui_backlight_sync_ignition(new_ignition);
53	                sd_card_on_ignition_on();
54	            } else if (current_can_data.ignition == 1 && new_ignition == 0) {
55	                can_app_save_fuel_consumption();
56	                ui_backlight_sync_ignition(new_ignition);
57	                sd_card_on_ignition_off();
58	            }
59	            
60	            current_can_data.ignition = new_ignition;
61	            
62	            uint8_t raw_fuel_data = (uint8_t)message.data[5] & 0x7F;
63	            if (raw_fuel_data != 0x7F)
